1	// SPDX-FileCopyrightText: Copyright (c) 2024-2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
2	// SPDX-License-Identifier: Apache-2.0
3	
4	//! NCCL collective broadcast operations for block data.
5	//!
6	//! This module provides functions for broadcasting block data across multiple
7	//! GPUs using NCCL collective operations.
8	
9	use super::*;
10	
11	use std::cell::Cell;
12	use std::ffi::c_void;
13	use std::ops::Range;
14	
15	use anyhow::{Context, Result};
16	use cudarc::driver::sys::CUstream;
17	use cudarc::nccl::sys::{
18	    ncclBcast, ncclComm_t, ncclDataType_t, ncclGroupEnd, ncclGroupStart, ncclResult_t,
19	};
20	
21	/// Check NCCL result and convert to anyhow::Result
22	fn check_nccl_result(result: ncclResult_t) -> Result<()> {
23	    if result == ncclResult_t::ncclSuccess {
24	        Ok(())
25	    } else {
26	        anyhow::bail!("NCCL error: {:?}", result)
27	    }
28	}
29	
30	/// RAII guard for NCCL group operations.
31	///
32	/// Calls `ncclGroupStart` in [`NcclGroup::new`] and `ncclGroupEnd` in [`NcclGroup::end`]
33	/// (or in [`Drop`] if [`NcclGroup::end`] was not called).
34	/// Use this to batch multiple NCCL operations efficiently.
35	///
36	/// **Call [`NcclGroup::end`] before dropping** so submission errors can be observed.
37	/// If you drop without calling `end()`, [`Drop`] will call `ncclGroupEnd()` and panic on error.
38	///
39	/// # Example
40	/// ```ignore
41	/// let mut group = unsafe { NcclGroup::new()? };
42	/// unsafe { bcast_block(&block1, root, comm, stream)?; }
43	/// unsafe { bcast_block(&block2, root, comm, stream)?; }
44	/// group.end()?; // Submit the group; call before drop to observe errors
45	/// drop(group);
46	/// ```
47	///
48	/// # Safety
49	/// Creating an `NcclGroup` is unsafe because:
50	/// - All ranks must create and drop the group collectively
51	/// - NCCL operations between creation and drop must be valid
52	pub struct NcclGroup {
53	    /// Tracks whether `ncclGroupEnd` has been successfully called (via `end()` or will be in `Drop`).
54	    ended: Cell<bool>,
55	}
56	
57	impl NcclGroup {
58	    /// Start a new NCCL group.
59	    ///
60	    /// Calls `ncclGroupStart`. All ranks must call this collectively.
61	    ///
62	    /// # Safety
63	    /// - All ranks must call this collectively
64	    /// - Call [`NcclGroup::end`] before drop to observe submission errors; the group must be ended before any synchronization
65	    pub unsafe fn new() -> Result<Self> {
66	        let result = unsafe { ncclGroupStart() };
67	        check_nccl_result(result).context("ncclGroupStart failed")?;
68	        Ok(Self {
69	            ended: Cell::new(false),
70	        })
71	    }
72	
73	    /// End the NCCL group and submit all queued operations.
74	    ///
75	    /// Calls `ncclGroupEnd()`. Call this before dropping the guard so submission
76	    /// errors can be observed. If this returns `Ok(())`, [`Drop`] will not call
77	    /// `ncclGroupEnd` again. If you drop without calling `end()`, [`Drop`] will
78	    /// call `ncclGroupEnd()` and panic on error.
79	    ///
80	    /// Returns an error if the group was already ended or if `ncclGroupEnd` fails.
81	    pub fn end(&self) -> Result<()> {
82	        if self.ended.get() {
83	            anyhow::bail!("NcclGroup::end called twice");
84	        }
85	        let result = unsafe { ncclGroupEnd() };
86	        check_nccl_result(result).context("ncclGroupEnd failed")?;
87	        self.ended.set(true);
88	        Ok(())
89	    }
90	}
91	
92	impl Drop for NcclGroup {
93	    fn drop(&mut self) {
94	        if self.ended.get() {
95	            return; // end() already called ncclGroupEnd successfully
96	        }
97	        // Safety: We started the group in NcclGroup::new (ncclGroupStart); we must end it.
98	        // Panic on error so we do not silently swallow ncclGroupEnd failures.
99	        let result = unsafe { ncclGroupEnd() };
100	        if result != ncclResult_t::ncclSuccess {
101	            panic!(
102	                "ncclGroupEnd failed in NcclGroup drop: {:?}. Call NcclGroup::end() before drop to handle errors.",
103	                result
104	            );
105	        }
106	    }
107	}
108	
109	/// Broadcast a block to all ranks.
110	///
111	/// If the block is fully contiguous, uses a single NCCL broadcast call.
112	/// Otherwise, falls back to layer-by-layer broadcast via [`bcast_layer`].
113	///
114	/// This function should be called from within an [`NcclGroup`] scope for
115	/// efficient batching of multiple broadcasts.
116	///
117	/// # Safety
118	/// - `comm` must be a valid NCCL communicator
119	/// - `stream` must be a valid CUDA stream
120	/// - All ranks must call this collectively with matching parameters
121	/// - The block's memory must be valid GPU memory accessible by the NCCL communicator
122	/// - Should be called within an [`NcclGroup`] scope
123	///
124	/// # Arguments
125	/// * `block` - The block to broadcast (source on root, destination on other ranks)
126	/// * `root` - The rank that owns the source data
127	/// * `comm` - The NCCL communicator
128	/// * `stream` - The CUDA stream to use for the operation
129	pub unsafe fn bcast_block<B>(block: &B, root: i32, comm: ncclComm_t, stream: CUstream) -> Result<()>
130	where
131	    B: BlockDataProvider,
132	{
133	    let data = block.block_data();
134	
135	    if data.is_fully_contiguous() {
136	        let view = data.block_view().context("Failed to get block view")?;
137	        let ptr = unsafe { view.as_ptr() } as usize;
138	        let size = view.size();
139	
140	        let result = unsafe {
141	            ncclBcast(
142	                ptr as *mut c_void,
143	                size,
144	                ncclDataType_t::ncclChar,
145	                root,
146	                comm,
147	                stream.cast(),
148	            )
149	        };
150	        check_nccl_result(result).context("ncclBcast failed")
151	    } else {
152	        // Fall back to layer-by-layer broadcast for non-contiguous blocks
153	        unsafe { bcast_layer(block, None, root, comm, stream) }
154	    }
155	}
156	
157	/// Broadcast block layers to all ranks.
158	///
159	/// Iterates over layer views and broadcasts each one. Use this when only a
160	/// subset of layers should be broadcast, or when the block layout is not
161	/// fully contiguous.
162	///
163	/// This function should be called from within an [`NcclGroup`] scope for
164	/// efficient batching of multiple broadcasts.
165	///
166	/// # Safety
167	/// - `comm` must be a valid NCCL communicator
168	/// - `stream` must be a valid CUDA stream
169	/// - All ranks must call this collectively with matching parameters
170	/// - The block's memory must be valid GPU memory accessible by the NCCL communicator
171	/// - Should be called within an [`NcclGroup`] scope
172	///
173	/// # Arguments
174	/// * `block` - The block containing layers to broadcast
175	/// * `layer_range` - Optional range of layers to broadcast. If None, broadcasts all layers.
176	/// * `root` - The rank that owns the source data
177	/// * `comm` - The NCCL communicator
178	/// * `stream` - The CUDA stream to use for the operation
179	pub unsafe fn bcast_layer<B>(
180	    block: &B,
181	    layer_range: Option<Range<usize>>,
182	    root: i32,
183	    comm: ncclComm_t,
184	    stream: CUstream,
185	) -> Result<()>
186	where
187	    B: BlockDataProvider,
188	{
189	    let data = block.block_data();
190	    let layer_range = layer_range.unwrap_or(0..data.num_layers());
191	
192	    for layer_idx in layer_range {
193	        for outer_idx in 0..data.num_outer_dims() {
194	            let view = data
195	                .layer_view(layer_idx, outer_idx)
196	                .context("Failed to get layer view")?;
197	            let ptr = unsafe { view.as_ptr() } as usize;
198	            let size = view.size();
199	
200	            let result = unsafe {
201	                ncclBcast(
202	                    ptr as *mut c_void,
203	                    size,
204	                    ncclDataType_t::ncclChar,
205	                    root,
