213	        }
214	        TransferStrategy::CudaAsyncH2D
215	        | TransferStrategy::CudaAsyncD2H
216	        | TransferStrategy::CudaAsyncD2D => {
217	            tracing::debug!(
218	                "Transfer: Using CUDA strategy: {:?}",
