232	                        let selected_stream = ctx.stream();
233	                        cuda::copy_blocks_with_customized_kernel(
234	                            sources,
235	                            targets,
236	                            selected_stream.as_ref(),
237	                            &ctx,
238	                        )?;
239	                    }
240	                    CudaTransferMode::Default => {
241	                        for (src, dst) in sources.iter().zip(targets.iter_mut()) {
242	                            cuda::copy_block(
243	                                src,
244	                                dst,
245	                                ctx.stream().as_ref(),
246	                                RB::write_to_strategy(),
247	                            )?;
248	                        }
249	                    }
250	                };
251	                ctx.cuda_event(tx)?;
252	
253	                Ok(rx)
254	            } else {
255	                // Fall back to individual copy for D2Dblocks
256	                for (src, dst) in sources.iter().zip(targets.iter_mut()) {
257	                    cuda::copy_block(src, dst, ctx.stream().as_ref(), RB::write_to_strategy())?;
258	                }
