191	    pub async fn execute_batched_transfer(
192	        &self,
193	        handler: &BlockTransferHandler,
194	        request: BlockTransferRequest,
195	    ) -> Result<()> {
196	        // In replicated mode, execute sequentially (all ranks must participate together)
197	        // to ensure proper NCCL collective synchronization
198	        if handler.transfer_mode() == TransferMode::Replicated {
199	            return handler.execute_transfer_direct(request).await;
200	        }
201	
202	        let blocks = request.blocks();
203	        let num_blocks = blocks.len();
204	
205	        if num_blocks <= self.max_batch_size {
206	            return handler.execute_transfer_direct(request).await;
207	        }
208	
209	        let batches = blocks.chunks(self.max_batch_size);
210	
211	        let batch_futures: Vec<_> = batches
212	            .map(|batch| {
213	                let batch_request = BlockTransferRequest {
214	                    from_pool: *request.from_pool(),
215	                    to_pool: *request.to_pool(),
216	                    blocks: batch.to_vec(),
217	                    connector_req: None,
218	                };
219	                handler.execute_transfer_direct(batch_request)
220	            })
221	            .collect();
222	
223	        // Execute all batches concurrently
224	        tracing::debug!("Executing {} batches concurrently", batch_futures.len());
225	
226	        match try_join_all(batch_futures).await {
227	            Ok(_) => Ok(()),
228	            Err(e) => {
229	                tracing::error!("Batched connector transfer failed: {}", e);
230	                Err(e)
231	            }
232	        }
233	    }
234	}
